module mv_stream_if #(
  parameter int LANES = 16,
  parameter int MAT_DATA_W = 128
) (
  input  logic [MAT_DATA_W-1:0]      mat_data_in,
  output logic signed [LANES*8-1:0]  mat_lanes_out
);
  genvar i;
  generate
    for (i = 0; i < LANES; i++) begin : g_unpack
      assign mat_lanes_out[i*8 +: 8] = mat_data_in[i*8 +: 8];
    end
  endgenerate
endmodule

module mv_vec_buffer #(
  parameter int MAX_N = 256,
  parameter int LANES = 16
) (
  input  logic                          clk,
  input  logic                          rst_n,
  input  logic                          wr_en,
  input  logic [$clog2(MAX_N)-1:0]      wr_addr,
  input  logic signed [7:0]             wr_data,
  input  logic [$clog2(MAX_N)-1:0]      rd_chunk_base,
  output logic signed [LANES*8-1:0]     rd_data
);
  logic signed [7:0] mem [0:MAX_N-1];

  always_ff @(posedge clk) begin
    if (wr_en) mem[wr_addr] <= wr_data;
  end

  integer j;
  always_comb begin
    for (j = 0; j < LANES; j++) begin
      if ((rd_chunk_base + j) < MAX_N)
        rd_data[j*8 +: 8] = mem[rd_chunk_base + j];
      else
        rd_data[j*8 +: 8] = '0;
    end
  end
endmodule

module mv_mac16_core #(
  parameter int LANES = 16
) (
  input  logic                         clk,
  input  logic                         rst_n,
  input  logic                         compute_en,
  input  logic                         new_row,
  input  logic [LANES-1:0]             lane_valid_mask,
  input  logic signed [LANES*8-1:0]    mat_lane_data,
  input  logic signed [LANES*8-1:0]    vec_lane_data,
  output logic signed [31:0]           row_accum_out,
  output logic                         row_done_pulse
);
  logic signed [31:0] sum32;
  integer i;
  logic signed [7:0] m_i, v_i;
  logic signed [15:0] p_i;

  always_comb begin
    sum32 = 32'sd0;
    for (i = 0; i < LANES; i++) begin
      if (lane_valid_mask[i]) begin
        m_i = mat_lane_data[i*8 +: 8];
        v_i = vec_lane_data[i*8 +: 8];
        p_i = m_i * v_i;
        sum32 = sum32 + {{16{p_i[15]}}, p_i};
      end
    end
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      row_accum_out  <= 32'sd0;
      row_done_pulse <= 1'b0;
    end else begin
      row_done_pulse <= 1'b0;
      if (new_row) row_accum_out <= 32'sd0;
      if (compute_en) begin
        row_accum_out <= row_accum_out + sum32;
        row_done_pulse <= 1'b1;
      end
    end
  end
endmodule

module mv_postproc (
  input  logic               clk,
  input  logic               rst_n,
  input  logic               in_valid,
  input  logic signed [31:0] in_data,
  input  logic               bias_en,
  input  logic               relu_en,
  input  logic               bias_valid,
  input  logic signed [31:0] bias_data,
  input  logic               out_ready,
  output logic               out_valid,
  output logic signed [31:0] out_data,
  output logic               in_ready
);
  logic signed [31:0] pre_act;
  logic signed [31:0] post_act;

  always_comb begin
    in_ready = (~out_valid) | out_ready;
    pre_act = in_data;
    if (bias_en) pre_act = in_data + bias_data;
    post_act = pre_act;
    if (relu_en && pre_act[31]) post_act = 32'sd0;
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      out_valid <= 1'b0;
      out_data  <= 32'sd0;
    end else begin
      if (in_valid && in_ready) begin
        if (!bias_en || bias_valid) begin
          out_data  <= post_act;
          out_valid <= 1'b1;
        end
      end else if (out_valid && out_ready) begin
        out_valid <= 1'b0;
      end
    end
  end
endmodule

module mv_ctrl_fsm #(
  parameter int MAX_M = 256,
  parameter int MAX_N = 256,
  parameter int LANES = 16,
  parameter int CMD_W = 64
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     cmd_accept,
  input  logic [CMD_W-1:0]         cmd_data,
  input  logic                     vec_xfer,
  input  logic                     mat_xfer,
  input  logic                     bias_xfer,
  input  logic                     out_xfer,
  output logic [15:0]              cfg_M,
  output logic [15:0]              cfg_N,
  output logic                     cfg_bias_en,
  output logic                     cfg_relu_en,
  output logic                     state_compute_en,
  output logic [LANES-1:0]         lane_valid_mask,
  output logic                     status_busy,
  output logic                     status_error
);
  typedef enum logic [1:0] {IDLE, LOAD_VEC, COMPUTE_ROWS, DONE} st_t;
  st_t st;
  logic [15:0] vec_cnt, row_cnt, chunk_cnt;
  logic [15:0] chunks_per_row;
  logic [4:0]  rem;

  always_comb begin
    chunks_per_row = (cfg_N + LANES - 1) / LANES;
    rem = cfg_N % LANES;
    lane_valid_mask = {LANES{1'b1}};
    if ((chunk_cnt == chunks_per_row - 1) && (rem != 0)) lane_valid_mask = (16'h0001 << rem) - 1;
    state_compute_en = (st == COMPUTE_ROWS) && mat_xfer;
    status_busy = (st != IDLE);
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      st <= IDLE;
      cfg_M <= 16'd0;
      cfg_N <= 16'd0;
      cfg_bias_en <= 1'b0;
      cfg_relu_en <= 1'b0;
      vec_cnt <= 16'd0;
      row_cnt <= 16'd0;
      chunk_cnt <= 16'd0;
      status_error <= 1'b0;
    end else begin
      case (st)
        IDLE: begin
          vec_cnt <= 16'd0; row_cnt <= 16'd0; chunk_cnt <= 16'd0;
          if (cmd_accept) begin
            cfg_M <= cmd_data[15:0];
            cfg_N <= cmd_data[31:16];
            cfg_bias_en <= cmd_data[32];
            cfg_relu_en <= cmd_data[33];
            if ((cmd_data[15:0] < 1) || (cmd_data[15:0] > MAX_M) || (cmd_data[31:16] < 1) || (cmd_data[31:16] > MAX_N)) begin
              status_error <= 1'b1;
              st <= DONE;
            end else st <= LOAD_VEC;
          end
        end
        LOAD_VEC: begin
          if (vec_xfer) begin
            vec_cnt <= vec_cnt + 1;
            if (vec_cnt + 1 == cfg_N) st <= COMPUTE_ROWS;
          end
        end
        COMPUTE_ROWS: begin
          if (mat_xfer) begin
            if (chunk_cnt + 1 == chunks_per_row) begin
              chunk_cnt <= 16'd0;
              if (row_cnt + 1 == cfg_M) st <= DONE;
              else row_cnt <= row_cnt + 1;
            end else chunk_cnt <= chunk_cnt + 1;
          end
          if (bias_xfer && !cfg_bias_en) status_error <= 1'b1;
        end
        DONE: begin
          if (out_xfer && (row_cnt + 1 == cfg_M || status_error)) st <= IDLE;
        end
      endcase
    end
  end
endmodule
